function pauseView() {
  const reason=state.session.pauseReason;
  return `<div class="pause-layer" role="dialog" aria-modal="true" aria-labelledby="pause-title"><div class="pause-content"><div class="pause-symbol">${icon('leaf')}</div><p class="kicker">A gentle return</p><h2 id="pause-title">${reason==='drift'?'Notice. Reset. Return.':'Welcome back.'}</h2><p>${reason==='drift'?'No penalty for noticing your attention drift. Let the distraction go, take a comfortable breath, and return to one point.':'Your place and written answer were saved when possible. Take a moment before returning. This round is marked as interrupted.'}</p>${btn('continue-pause','Continue '+icon('arrow'))}<br>${btn('exit','Save & leave','ghost')}</div></div>`;
}
function render(focus=true) {
  const isSession = route==='session' && state.session;
  document.body.classList.toggle('large-text',state.settings.largeText);
  const warning=storageError?`<div class="notice warning" role="alert">${e(storageError)}</div>`:'';
  if(isSession && !state.session.paused && ['study','hint','feedback'].includes(state.session.stage)){noteExposure();persist();}
  const body=isSession?sessionView():route==='today'?todayView():route==='library'?libraryView():route==='progress'?progressView()+memoryProgress():route==='memory'?memoryView():settingsView();
  $('#app').innerHTML = header(!!isSession)+`<main id="main" tabindex="-1" class="${isSession?'session-main':''}">${warning}${body}</main>`+(isSession?'':nav());
  if (focus) { window.scrollTo(0,0); const target=state.session?.paused&&isSession?$('#pause-title'):$('#main h1')||$('#main');target?.setAttribute('tabindex','-1');target?.focus({preventScroll:true}); }
}
function startSession(options={}) {
  if (state.session && !confirm('Replace the unfinished session? Completed rounds are kept, but the current unsaved round will end.')) return;
  try { state.session=C.planSession(state,D,options);initRound();route='session';persist();render(); }
  catch(err) {toast(err.message,6500);}
}
function pause(reason) {
  const s=state.session;
  if (!s || s.paused || ['result','complete'].includes(s.stage)) return;
  const c=s.current;
  if (['study','hint','feedback'].includes(s.stage)) noteExposure();
  if (c) {
    if (s.stage==='study'&&c.studyStartedAt) {c.studyMs+=Math.max(0,Date.now()-c.studyStartedAt);c.studyStartedAt=0;}
    if (reason==='drift') c.drifts++; else c.interrupted=true;
  }
  s.paused=true;s.pauseReason=reason;clearTimeout(draftTimer);persist();render(false);
}
function beginRound() {
  const {s,q,c}=currentRound(), now=Date.now();c.startedAt=now;
  if (q.phase==='review'||q.phase==='early') {s.stage='recall';c.hiddenAt=state.progress[q.id].lastExposedAt;}
  else {s.stage='study';c.studyStartedAt=now;const p=state.progress[q.id];state.progress[q.id]={mode:q.mode,count:q.count,createdAt:p?.createdAt||now,reps:p?.reps||0,stage:p?.stage||0,due:p?.due||now,lastExposedAt:now,lastReviewed:p?.lastReviewed||0};}
  persist();render();
}
function saveRound() {
  const {s,q,c,points,card}=currentRound(); if(s.stage!=='feedback')return;
  if(q.mode==='meaning'&&c.grades.some(g=>g===null)) {toast('Rate every idea as missing, partial, or full before saving.');$(`[name="grade-${c.grades.findIndex(x=>x===null)}"]`)?.focus();return;}
  const matches=q.mode==='wording'?points.map((p,i)=>C.compareWords(p,c.original[i]||'')):[];
  const perPoint=q.mode==='meaning'?c.grades.slice():matches.map(m=>m.score), score=C.mean(perPoint), now=Date.now();
  const r={id:C.uid('try'),cardId:q.id,title:card.title,mode:q.mode,phase:q.phase,count:q.count,at:now,score,perPoint,original:c.original.slice(),prompted:c.prompted?.slice()||null,hintUsed:c.hintUsed,drifts:c.drifts,interrupted:c.interrupted,attention:c.attention,lagMs:c.originalLagMs,studyMs:c.studyMs,exactCount:matches.filter(m=>m.exact).length,custom:card.custom===true};
  state.records.push(r);if(state.records.length>1500)state.records=state.records.slice(-1500);
  const before=state.progress[q.id]||{mode:q.mode,count:q.count,createdAt:now,reps:0,stage:0};
  state.progress[q.id]=C.schedule(before,score,c.originalLagMs,now);s.results.push(r.id);s.stage='result';persist();render();
}
async function downloadJSON(data,name) {
  const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type:'application/json'});
  const file=typeof File==='function'?new File([blob],name,{type:'application/json'}):null;
  if(file&&navigator.canShare&&navigator.canShare({files:[file]})) {
    try {await navigator.share({files:[file],title:'Focus Recall backup'});toast('Backup shared. Keep it in a private location.');return;}
    catch(err) {if(err.name==='AbortError')return;}
  }
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('Backup exported. Keep it somewhere private.');
}
async function handleAction(el) {
  const action=el.dataset.action;
  if(action==='nav') {noteMemoryExposure();if(route==='memory'&&el.dataset.view!=='memory'&&state.memory.active)state.memory.active.interrupted=true;route=el.dataset.view;persist();render();return;}
  if(action.startsWith('mem-'))return memoryAction(el);
  if(action==='reading-pair')return startSession({size:2});
  if(action==='start')return startSession();
  if(action==='fresh')return startSession({size:2,kind:'fresh'});
  if(action==='practice-card')return startSession({size:2,preferred:el.dataset.id});
  if(action==='resume-session') {route='session';render();return;}
  if(action==='discard-session') {if(confirm('End this saved session? Completed rounds and review dates will stay.')){state.session=null;persist();render();}return;}
  if(action==='exit') {if(state.session&&!['result','complete'].includes(state.session.stage))pause('return');route='today';persist();render();return;}
  if(action==='continue-pause') {const s=state.session;if(!s)return;s.paused=false;if(s.stage==='study')s.current.studyStartedAt=Date.now();persist();render();return;}
  if(action==='begin-round')return beginRound();
  if(action==='drift')return pause('drift');
  if(action==='next-point'||action==='previous-point') {const {c,q}=currentRound();c.readIndex=Math.max(0,Math.min(q.count-1,c.readIndex+(action==='next-point'?1:-1)));persist();render(false);return;}
  if(action==='hide-source') {const {s,c}=currentRound();if(s.stage!=='study')return;c.studyMs+=c.studyStartedAt?Math.max(0,Date.now()-c.studyStartedAt):0;c.studyStartedAt=0;c.hiddenAt=Date.now();s.stage='recall';persist();render();return;}
  if(action==='hint') {const {s,c}=currentRound();if(s.stage!=='choice')return;c.hintUsed=true;c.prompted=c.original.slice();s.stage='hint';persist();render();return;}
  if(action==='reveal') {const {s}=currentRound();if(s.stage!=='choice')return;s.stage='feedback';persist();render();return;}
  if(action==='save-round')return saveRound();
  if(action==='next-round') {const s=state.session;if(s.stage!=='result')return;if(s.index===s.queue.length-1){s.stage='complete';state.completedSessions++;}else{s.index++;initRound();}persist();render();return;}
  if(action==='finish-session') {state.session=null;route='today';persist();render();return;}
  if(action==='add-text') {route='library';addOpen=true;render();return;}
  if(action==='toggle-add') {addOpen=!addOpen;render(false);if(addOpen)$('#passage-title')?.focus();return;}
  if(action==='delete-card') {const id=el.dataset.id;if(state.session?.queue.some(q=>q.id===id)){toast('End the saved session before deleting a passage it uses.');return;}if(confirm('Delete this passage, its answers, and its review history from this device?')){state.custom=state.custom.filter(c=>c.id!==id);state.records=state.records.filter(r=>r.cardId!==id);delete state.progress[id];persist();render(false);}return;}
  if(action==='set-points'||action==='level-up') {state.settings.points=Number(el.dataset.count);persist();render(false);toast('New built-in passages will use '+state.settings.points+' points.');return;}
  if(action==='export') {persist();return downloadJSON({...state,exportedAt:new Date().toISOString()},'focus-recall-backup-'+C.localDay()+'.json');}
  if(action==='export-recovery')return downloadJSON(recoveryRaw,'focus-recall-recovery-'+C.localDay()+'.json');
  if(action==='import') {$('#import-file').click();return;}
  if(action==='request-storage') {try{const granted=await navigator.storage.persist();$('#storage-detail').textContent=granted?'The browser granted persistent-storage mode. Keep backups anyway; explicit deletion can still remove data.':'The browser did not grant persistent storage. The app still works; keep regular backups.';}catch(err){toast('Storage-retention permission is not available here. Keep backups.');}return;}
  if(action==='update-app') {if(state.session||state.memory.active){toast('Finish or end your saved exercises before applying an update.');return;}registration?.waiting?.postMessage({type:'ACTIVATE_UPDATE'});navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});return;}
  if(action==='clear-data') {if(!confirm('Permanently delete all Focus Recall practice data from this browser? Export a backup first if you need it.'))return;try{localStorage.removeItem(KEY);persistOkay=true;storageError='';recoveryRaw='';}catch(err){toast('Browser data could not be cleared. Use the browser’s site-data controls.');return;}state=C.newState();route='today';persist();render();toast('Local practice data cleared.');}
}
$('#app').addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el||el.disabled)return;
  Promise.resolve(handleAction(el)).catch(err=>{console.error(err);toast('That action could not finish. Your completed rounds are kept when device storage is available.',6500);});
});
$('#app').addEventListener('input',event=>{
  const el=event.target;
  if(el.matches('[data-answer]')&&state.session){const c=state.session.current;const target=state.session.stage==='hint'?c.prompted:c.answers;target[Number(el.dataset.answer)]=el.value.slice(0,2000);queueSave();}
  if(el.id==='passage-title')libraryDraft.title=el.value;
  if(el.id==='passage-points')libraryDraft.points=el.value;
  if(el.id==='passage-source')libraryDraft.sourceText=el.value;
  if(el.matches('[data-reading-image]')&&state.session){state.session.current.images??=[];state.session.current.images[Number(el.dataset.readingImage)]=el.value.slice(0,500);queueSave();}
});
$('#app').addEventListener('change',async event=>{
  const el=event.target;
  if(el.matches('[data-grade]')&&state.session){state.session.current.grades[Number(el.dataset.grade)]=Number(el.value);persist();}
  if(el.name==='attention'&&state.session){state.session.current.attention=el.value;persist();}
  if(el.id==='passage-mode')libraryDraft.mode=el.value;
  if(el.id==='reading-view'){state.settings.readingView=el.value==='spotlight'?'spotlight':'all';persist();toast('Reading view updated.');}
  if(el.id==='large-text'){state.settings.largeText=el.checked;persist();document.body.classList.toggle('large-text',el.checked);}
  if(el.id==='import-file'&&el.files[0]){
    const file=el.files[0];
    try{
      if(file.size>5*1024*1024)throw new Error('Choose a backup smaller than 5 MB.');
      const next=C.validateBackup(JSON.parse(await file.text()),D.map(c=>c.id));
      if(!confirm(`Replace this device’s data with ${next.custom.length} custom passages and ${next.records.length} reading results, ${next.memory.drills.length} mnemonic exercises, and ${next.memory.records.length} mnemonic results? Unfinished rounds will not be restored.`)){el.value='';return;}
      // Write the validated replacement first; do not discard the in-memory state on failure.
      localStorage.setItem(KEY,JSON.stringify(next));state=next;persistOkay=true;storageError='';recoveryRaw='';route='today';render();toast('Backup restored.');
    }catch(err){toast('Backup not restored: '+err.message,7000);el.value='';}
  }
});
$('#app').addEventListener('submit',event=>{
  event.preventDefault();const form=event.target;
  if(form.id==='recall-form'){
    const {s,c}=currentRound(),hinted=s.stage==='hint';
    if(!hinted&&s.stage!=='recall')return;
    const answers=Array.from(form.querySelectorAll('textarea')).map(t=>t.value.slice(0,2000));
    if(!answers.some(a=>a.trim())&&!confirm('Capture a blank attempt? It is okay not to recall the passage; you can still learn from the feedback.'))return;
    if(hinted){c.prompted=answers;s.stage='feedback';}
    else{c.answers=answers;c.original=answers.slice();const lag=Date.now()-c.hiddenAt;c.originalLagMs=Math.max(0,lag);if(lag<0){c.clockWarning=true;c.interrupted=true;}s.stage='choice';}
    clearTimeout(draftTimer);persist();render();
  }
  if(form.id==='add-form'){
    const title=form.elements.title.value.trim();const points=form.elements.points.value.split(/\r?\n/).map(t=>t.trim().replace(/^(?:[•*\-]\s+|\d+[.)]\s+)/,'')).filter(Boolean);
    const error=$('#add-error');
    if(!title||title.length>80){error.textContent='Add a title of 1–80 characters.';return;}
    if(points.length<2||points.length>4){error.textContent='Use two, three, or four target points, one per line.';return;}
    if(points.some(p=>p.length>300||C.tokens(p).length>35||C.tokens(p).length<1)){error.textContent='Keep each point to 1–35 words and no more than 300 characters. Shorter sentences are easier to start with.';return;}
    if(state.custom.length>=120){error.textContent='This version supports 120 custom passages. Export a backup, then remove an older passage.';return;}
    const mode=form.elements.mode.value;const sourceText=form.elements.sourceText.value.trim().slice(0,6000);
    state.custom.push({id:C.uid('user'),title,points,sourceText,custom:true,createdAt:Date.now(),preferredMode:['meaning','wording'].includes(mode)?mode:null});
    libraryDraft={title:'',points:'',mode:'',sourceText:''};addOpen=false;persist();render();toast('Passage saved. Practice it in a balanced pair.');
  }
});
document.addEventListener('visibilitychange',()=>{if(document.hidden){noteMemoryExposure();if(state.memory.active)state.memory.active.interrupted=true;clearTimeout(draftTimer);if(route==='session'&&state.session)pause('return');persist();}});
window.addEventListener('pagehide',()=>{noteMemoryExposure();clearTimeout(draftTimer);persist();});
window.addEventListener('online',()=>updateCacheLabel());window.addEventListener('offline',()=>updateCacheLabel());
function updateCacheLabel(){const el=$('#cache-status');if(el&&cacheReady)el.textContent=navigator.onLine?'Offline ready':'Offline';}
async function registerOffline() {
  if(window.FOCUS_PREVIEW||!('serviceWorker' in navigator)||!window.isSecureContext||location.protocol==='file:')return;
  try{
    registration=await navigator.serviceWorker.register('./sw.js',{scope:'./'});
    await navigator.serviceWorker.ready;cacheReady=true;updateCacheLabel();
    registration.addEventListener('updatefound',()=>{const worker=registration.installing;if(worker)worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller)toast('An app update is ready. Finish your session, then apply it in Settings.',6500);});});
  }catch(err){console.warn('Offline setup unavailable:',err);toast('Offline caching could not finish. Reopen online before relying on offline use.',6500);}
}
// Memory studio v3 — all practice material is generated locally.
let memRouteChoice='',memRouteOpen=false,memFilter='all';
const memDescriptions=Object.fromEntries(M.KINDS.map(k=>[k,M.SPECS[k].desc]));
const memUnit=d=>M.SPECS[d.kind].unit;
const memScoreLabel=d=>M.SPECS[d.kind].unordered?'items recovered':M.SPECS[d.kind].cued?'cue accuracy':'order accuracy';
const memObject=w=>`<span class="object-icon" aria-hidden="true">${e(M.OBJECTS[w]||'◇')}</span><span>${e(w)}</span>`;
function memoryHomeCard(){const m=state.memory,n=m.drills.filter(d=>d.reps>0&&d.due<=Date.now()).length;return `<section class="card mnemonic-home"><div><p class="kicker">Memory studio · 20 exercise types</p><h2>A bigger toolkit.</h2><p>Visual patterns, names, sequences, stories and more.<br>Explore a different way to remember.</p><div class="btn-row">${btn('nav',m.active?'Resume your memory exercise':'Explore the Memory studio','secondary','data-view="memory"')}<span class="small muted">${n} due for review</span></div></div><span class="mnemonic-symbol" aria-hidden="true">⌘</span></section>`;}
function readingMnemonicNotes(points,c){const palace=state.memory.palaces.find(p=>p.id!=='palace-example')||state.memory.palaces[0];return `<details class="card mnemonic-notes"><summary>Optional: give each point a cue</summary><p class="small muted">Turn the idea into a scene at a familiar place. These notes disappear when you hide the source. For exact wording, also rehearse the phrase itself: an image is not a word-for-word transcript.</p>${points.map((p,i)=>`<div class="field"><label for="reading-image-${i}">${i+1}. ${e(palace?.places[i]||'Your place '+(i+1))}</label><input type="text" id="reading-image-${i}" data-reading-image="${i}" maxlength="500" value="${e(c.images?.[i]||'')}" placeholder="Your image or keyword…"></div>`).join('')}<p class="field-hint">Personalize your route in the Memory tab.</p></details>`;}
function learningHelp(){return `<section class="card"><h2>How the two studios work</h2><details><summary>Reading recall</summary><p>Read, hide, retrieve, check, return later. Reading pairs give equal practice to meaning and exact wording on different passages. Meaning is self-rated; wording uses a word-edit comparison, ignoring case, punctuation and extra spaces.</p></details><details><summary>20 memory exercises</summary><p>Four families cover mnemonic techniques, visual and spatial patterns, sequences and numbers, and everyday or reading details. Each card includes a method, a study stage, a recall task, feedback, and a link back to everyday learning. Fresh practice creates a new randomized set; a review deliberately returns to the saved set.</p></details><details><summary>Different tasks, different scores</summary><p>Grid snapshot, Vanishing objects, and Category clusters score items recovered in any order. Other tasks score the correct response at each position or cue. Repeated guesses never earn extra credit. Order reconstruction supplies the step tiles; it is cued ordering, not free recall. Names & introductions uses fictional names and object badges, not face recognition. Map updates scores final positions, not the starting map.</p><p>Text matching ignores case and punctuation, not arbitrary synonyms or misspellings. Appointment times accept HH:MM or H:MM in 24-hour time; leading zeros in digit tasks matter. Scores from different tasks are not directly comparable.</p></details><details><summary>First attempts, cues and reviews</summary><p>Your first answer is locked before extra cues or feedback. Built-in task cues, such as a question, a speaker statement, or a blank grid, are part of that task and are labelled. Any additional notes or mnemonic hints appear only in a separate assisted attempt.</p><p>Reviews start with recall. Schedules use the first attempt: difficult material can return after about 10 minutes; most new material returns in a day. Successful spaced recalls can extend to 3, 7, 14 and 30 days. These are practical defaults. Three strong, uninterrupted delayed attempts at the same exercise and length can prompt a level suggestion; you can always choose manually.</p></details><details><summary>Book inspiration and original exercises</summary><p>Only the public introductory preview of Denis Bukin’s <em>Spy School: Are You Sharp Enough to Be a KGB Agent?</em> was consulted. The observation warm-up and progressive fictional practice format take inspiration from that preview. The expanded exercises, layouts, scenarios and generators are original, not a reproduction of the book or its complete course. No endorsement is implied.</p></details><details><summary>Useful practice, not a global memory score</summary><p>Practice scores describe these specific tasks. The app does not claim that a higher dice or grid score automatically improves every kind of memory. Try the suggested method on an article, introduction, or sequence you actually want to retain.</p></details></section>`;}
function memoryProgress(){const m=state.memory,used=M.KINDS.filter(k=>m.records.some(r=>r.kind===k));return `<section class="section-head"><h2>Memory skills</h2><span>${used.length} of 20 explored</span></section><section class="card"><p class="small muted">First attempts only. Results are kept separate by task. “Delayed” means at least 24 hours since the last recorded exposure.</p>${used.length?`<div class="memory-metrics">${used.map(k=>{const rs=m.records.filter(r=>r.kind===k),late=rs.filter(r=>r.lagMs>=C.DAY);return `<div class="memory-metric"><h3>${e(M.NAMES[k])}</h3><p><strong>${pct(C.mean(rs.slice(-10).map(r=>r.score)))}</strong> <span class="small muted">${rs.length} attempts</span></p><p class="small muted">Delayed: ${pct(C.mean(late.slice(-10).map(r=>r.score)))} · ${late.length} attempts</p></div>`;}).join('')}</div><p class="field-hint">Averages can mix lengths. Compare the exercise, length and delay below—not percentages across different tasks.</p><div class="mem-history">${m.records.slice(-12).reverse().map(r=>`<div class="history-row"><div><strong>${e(M.NAMES[r.kind])}</strong><p class="field-hint">${r.level} ${e(memUnit(r))} · ${lagLabel(r.lagMs)} delay${r.interrupted?' · interrupted':''}</p></div><span>${pct(r.score)}</span></div>`).join('')}</div>`:'<p class="muted">Your first saved exercise will appear here.</p>'}</section>`;}
function memoryView(){
 if(state.memory.active)return memExerciseView();
 const m=state.memory,due=m.drills.filter(d=>d.reps>0&&d.due<=Date.now()),selected=m.palaces.find(p=>p.id===memRouteChoice)||m.palaces[0],explored=new Set(m.records.map(r=>r.kind)).size;
 const included=k=>memFilter==='all'||memFilter==='favorites'&&m.favorites.includes(k)||M.SPECS[k].group===memFilter;
 const catalog=Object.entries(M.GROUPS).map(([g,label])=>{const ks=M.KINDS.filter(k=>M.SPECS[k].group===g&&included(k));return ks.length?`<section class="catalog-group" aria-label="${e(label)}"><div class="section-head"><h2>${e(label)}</h2><span>${ks.length} exercise types</span></div><div class="memory-grid">${ks.map(k=>{const s=M.SPECS[k],done=m.records.filter(r=>r.kind===k).length,fav=m.favorites.includes(k);return `<section class="card method-card" data-method="${k}"><div class="method-top"><span class="method-number">${String(M.KINDS.indexOf(k)+1).padStart(2,'0')}</span><button type="button" class="favorite-btn" data-action="mem-favorite" data-kind="${k}" aria-label="${fav?'Unfavorite':'Favorite'} ${e(s.name)}" aria-pressed="${fav}">${fav?'★':'☆'}</button></div><h3>${e(s.name)}</h3><p>${e(s.desc)}</p><span class="method-tag">${s.unordered?'Recall in any order':s.cued?'Cued recall':'Ordered recall'}${done?' · '+done+' saved':''}</span>${btn('mem-start','Start · '+m.level+' '+s.unit+' '+icon('arrow'),'secondary',`data-kind="${k}"`)}</section>`;}).join('')}</div></section>`:'';}).join('');
 return `<section class="page-intro memory-intro"><p class="kicker">Your expanded memory toolkit</p><h1>More ways<br>to make it stick.</h1><p>20 exercise types. Four levels. Fresh sets on every start.<br>Find a method, practise it, bring it back to your reading.</p><div class="studio-stats"><span><strong>20</strong> exercise types</span><span><strong>4</strong> skill families</span><span><strong>${explored}</strong> explored</span></div></section>
 <section class="card memory-controls"><div class="two-col"><div class="field"><label for="mem-level">Challenge size</label><select id="mem-level">${M.LEVELS.map((n,i)=>`<option value="${n}" ${m.level===n?'selected':''}>${['Starter','Steady','Stretch','Challenge'][i]} · ${n} units</option>`).join('')}</select></div><div class="field"><label for="mem-route-choice">Memory-palace route</label><select id="mem-route-choice">${m.palaces.map(p=>`<option value="${e(p.id)}" ${selected?.id===p.id?'selected':''}>${e(p.name)} · ${p.places.length} places</option>`).join('')||'<option value="">Add a route below</option>'}</select></div></div><p class="field-hint">A unit is a cell, object, name, step or number chunk, depending on the task. Nothing is timed. Choose a comfortable size.</p><div class="btn-row">${btn('mem-surprise','Surprise me '+icon('arrow'),'secondary')}<span class="small muted">${due.length} sets due for recall</span></div></section>
 <details class="card"><summary><strong>Attention warm-up · Notice &amp; return</strong></summary><p>Look closely at an everyday object. Notice its shape, small marks and textures. When your thoughts move elsewhere, notice what started the association and return to the object. Then look away, recall three details, and check.</p><p class="field-hint">An optional, unscored adaptation of the observation exercise in the book’s public introductory preview. The look-away recall step is our addition.</p></details>
 <div class="memory-filters segmented" role="group" aria-label="Filter memory exercises">${[['all','All 20'],...Object.entries(M.GROUPS),['favorites','★ Favorites']].map(([k,t])=>`<button type="button" data-action="mem-filter" data-filter="${k}" aria-pressed="${memFilter===k}">${e(t)}</button>`).join('')}</div>
 <div id="memory-catalog">${catalog||'<section class="card"><h2>Your favorites go here.</h2><p>Tap a star on any exercise card to keep it close.</p></section>'}</div>
 <section class="card"><div class="section-head"><h2>Your routes</h2>${btn('mem-route-toggle',memRouteOpen?'Close form':'Add a route','ghost')}</div><p class="small muted">Use a home, a walk, or another place you can picture clearly. Keep the order fixed. Distinct routes help keep active lists apart.</p>${m.palaces.map(p=>`<details class="route-details"><summary>${e(p.name)} <span class="muted">· ${p.places.length} places</span></summary><ol>${p.places.map(v=>`<li>${e(v)}</li>`).join('')}</ol><p class="field-hint">Existing exercises keep their own copy of these places.</p>${btn('mem-route-delete','Remove route','ghost',`data-id="${e(p.id)}"`)}</details>`).join('')}${memRouteOpen?`<form id="mem-route-form"><div class="field"><label for="mem-route-name">Route name</label><input type="text" required id="mem-route-name" name="routeName" maxlength="60" placeholder="My morning walk"></div><div class="field"><label for="mem-route-places">3–12 distinct places, one per line</label><textarea required id="mem-route-places" name="places" maxlength="1200" rows="6" placeholder="Front door&#10;Corner bakery&#10;Bus shelter"></textarea></div><button class="btn primary" type="submit">Save route</button></form>`:''}</section>
 <section class="card"><p class="kicker">Recall first, then revisit</p><h2>Your saved sets.</h2><p class="small muted">New set = fresh material. Review = the same saved challenge, with its original task cues but no study screen.</p>${m.drills.length?m.drills.slice().sort((a,b)=>a.due-b.due).map(d=>`<div class="history-row"><div><strong>${e(d.title)}</strong><p class="field-hint">${d.reps===0?'Not yet completed':d.due<=Date.now()?'Due now':'Next: '+dateLabel(d.due)}${d.palaceName?' · '+e(d.palaceName):''}</p><div class="btn-row">${btn('mem-review',d.reps===0?'Recall this set':d.due<=Date.now()?'Review':'Practice early','secondary',`data-id="${e(d.id)}"`)}${btn('mem-delete','Delete','ghost',`data-id="${e(d.id)}"`)}</div></div></div>`).join(''):'<p class="muted">Complete an exercise to start your collection.</p>'}</section><p class="small muted">Original, fictional practice material. No account, private codes, or personal data needed. Not the book’s full course or an endorsed companion.</p>`;
}
function noteMemoryExposure(){if(route!=='memory')return;const {a,d}=memContext();if(a&&d&&['study','assisted','feedback'].includes(a.stage))d.lastExposedAt=Date.now();}
function memContext(){const a=state.memory.active;return {a,d:a?state.memory.drills.find(x=>x.id===a.drillId):null};}
function memReference(d){if(d.kind==='pegs')return `<details class="card"><summary>The number-rhyme pegs</summary><p>${M.PEGS.map((x,i)=>(i+1)+' = '+e(x)).join(' · ')}</p><p class="small muted">Keep the same pegs from one exercise to the next.</p></details>`;if(d.kind==='digits')return `<details class="card"><summary>The digit-image key</summary><p>${M.SHAPES.map((x,i)=>i+' = '+e(x)).join(' · ')}</p></details>`;return '';}
function memGrid({selected=[],items=[],positions=[],interactive=false,action='mem-grid-cell',focus=''}){return `<div class="visual-grid" role="group" aria-label="Four by four memory grid. Rows A to D, columns 1 to 4.">${M.CELLS.map(cell=>{const index=positions.indexOf(cell),occupied=index>=0,active=selected.includes(cell);return interactive?`<button type="button" class="grid-cell ${active?'selected':''}" data-action="${action}" data-cell="${cell}" aria-pressed="${active}" aria-label="Cell ${cell}${active?', selected':''}"><span class="cell-label">${cell}</span><span aria-hidden="true">${active?'●':''}</span></button>`:`<div class="grid-cell ${active?'selected':''}" aria-label="Cell ${cell}${occupied?', '+e(items[index]):active?', filled':', empty'}"><span class="cell-label">${cell}</span>${occupied?memObject(items[index]):active?'<span aria-hidden="true">●</span>':''}</div>`;}).join('')}</div>`;}
function memDice(value){const dots={1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]};return `<span class="die" role="img" aria-label="Die showing ${Number(value)}">${Array.from({length:9},(_,i)=>`<i class="pip ${dots[value]?.includes(i)?'on':''}"></i>`).join('')}</span>`;}
function memStudy(d){
 const s=M.SPECS[d.kind],{a}=memContext(),i=a.studyIndex||0;let source='';
 if(d.kind==='grid')source=memGrid({selected:d.targets});
 else if(['locations','updates'].includes(d.kind))source=`<p class="kicker">Starting layout</p>${memGrid({items:d.anchors,positions:d.meta.positions})}${d.kind==='updates'?`<div class="instruction-panel"><p class="kicker">${i<d.level?'Move '+(i+1)+' of '+d.level:'All moves shown'}</p><p class="instruction-line">${i<d.level?e(d.meta.lines[i]):'Keep the final positions in mind. Hide the map when you are ready.'}</p>${i<d.level?btn('mem-step',i===d.level-1?'Finish instructions':'Next move '+icon('arrow'),'secondary'):''}<p class="field-hint">The diagram stays at the starting layout; update it mentally. The final map is hidden until feedback.</p></div>`:''}`;
 else if(d.kind==='dice')source=`<div class="dice-tray">${d.targets.map((t,i)=>`<div><span class="small muted">${i+1}</span>${memDice(t)}</div>`).join('')}</div>`;
 else if(d.kind==='missing')source=`<p class="small muted">Study all ${d.level*2} objects. ${d.level} will disappear.</p><div class="object-tray">${d.meta.source.map(w=>`<div class="object-tile">${memObject(w)}</div>`).join('')}</div>`;
 else if(['symbols','reverse'].includes(d.kind))source=`<div class="sequence-stage"><p class="kicker">${i<d.level?'Item '+(i+1)+' of '+d.level:'Sequence complete'}</p>${i<d.level?`<div class="sequence-symbol" role="img" aria-label="${e(d.meta.source[i])}">${e(d.kind==='symbols'?M.SYMBOLS[d.meta.source[i]]:d.meta.source[i])}</div><p class="small muted">${d.kind==='symbols'?e(d.meta.source[i]):'Recall in reverse order after the last digit.'}</p>${btn('mem-step',i===d.level-1?'Finish sequence':'Next '+icon('arrow'),'secondary')}`:'<h2>Hold the sequence.</h2><p>Move to recall when you are ready.</p>'}</div>`;
 else if(d.kind==='casefile')source=`<article class="case-note"><p class="kicker">Original field note · fictional</p><p>${d.meta.lines.map(e).join(' ')}</p></article><p class="field-hint">Recall will ask ${d.level} specific questions. Use the original names and item labels; full sentences are not needed.</p>`;
 else if(d.kind==='sources')source=`<div class="discussion">${d.meta.lines.map((line,i)=>`<div class="speech-note"><strong>${e(d.targets[i])}</strong><p>${e(d.anchors[i])}</p></div>`).join('')}</div>`;
 else if(d.kind==='names')source=`<div class="name-badges">${d.targets.map((t,i)=>`<section class="name-badge"><span class="object-icon" aria-hidden="true">${e(M.OBJECTS[d.meta.items[i]])}</span><strong>${e(t)}</strong><p class="small muted">${e(d.anchors[i])}</p></section>`).join('')}</div>`;
 else if(d.kind==='appointments')source=`<div class="diary">${d.targets.map((t,i)=>`<div class="diary-row"><strong class="mono">${e(t)}</strong><span>${e(d.anchors[i])}</span></div>`).join('')}</div>`;
 else if(d.kind==='categories')source=`<div class="category-list">${d.targets.map((t,i)=>`<div><strong>${e(t)}</strong><span class="method-tag">${e(d.anchors[i])}</span></div>`).join('')}</div>`;
 else if(d.kind==='chunks')source=`<div class="chunk-tray">${d.targets.map((t,i)=>`<div><span class="small muted">Block ${i+1}</span><strong class="mono">${e(t)}</strong></div>`).join('')}</div><p class="field-hint">${d.level*3} digits in ${d.level} blocks. Leading zeros are part of the number.</p>`;
 else source=`${d.kind==='palace'?`<p class="small muted">Route: ${e(d.palaceName)}</p>`:''}${memReference(d)}<div class="mem-source">${d.targets.map((t,i)=>`<section class="mem-source-row"><div class="mem-target"><span class="point-no">${i+1}</span><div>${d.anchors[i]?`<span class="small muted">${e(d.anchors[i])}</span><br>`:''}<strong>${e(t)}</strong></div></div><div class="field"><label for="mem-image-${i}">Your connection <span class="muted">(optional)</span></label><input type="text" id="mem-image-${i}" data-mem-image="${i}" maxlength="500" value="${e(d.images[i]||'')}" placeholder="An image, link or cue…"></div></section>`).join('')}</div>`;
 const stepped=['symbols','reverse','updates'].includes(d.kind),done=!stepped||i>=d.level;
 return `<p>${e(s.desc)}</p><aside class="method-tip"><strong>Try this method</strong><p>${e(s.tip)}</p></aside><div class="memory-study-source">${source}</div><details class="memory-notes"><summary>Your mnemonic notes (optional)</summary><div class="field"><label for="mem-set-title">Set label (visible during review)</label><input type="text" id="mem-set-title" maxlength="100" value="${e(d.title)}"><p class="field-hint">Name the occasion, not the answers, so you can identify this set later.</p></div><div class="field"><label for="mem-story">${d.kind==='acrostic'?'Your initial-letter sentence':'Your strategy, scene or story'}</label><textarea id="mem-story" maxlength="3000" rows="3" placeholder="These notes disappear during your first recall.">${e(d.story)}</textarea></div></details><p class="small muted">No countdown. Take the time you need; your notes disappear with the source.</p>${done?btn('mem-hide','Hide & recall '+icon('arrow')):'<p class="field-hint">Finish the sequence above to unlock recall.</p>'}`;
}
function memPrompt(d,i){if(M.SPECS[d.kind].cued&&d.anchors[i])return d.kind==='acrostic'?'Word '+(i+1)+' · starts with '+d.anchors[i]:d.anchors[i];return d.kind==='chunks'?'Block '+(i+1):d.kind==='dice'?'Die '+(i+1):d.kind==='reverse'?'Reverse digit '+(i+1):d.kind==='digits'?'Digit '+(i+1):'Item '+(i+1);}
function memAnswerForm(d,a,assisted=false){
 const values=assisted?(a.assisted||a.original):a.answers,s=M.SPECS[d.kind];let special='';
 if(d.kind==='grid')special=`<p>Tap ${d.level} cells. Tap a selected cell again to remove it.</p>${memGrid({selected:values.filter(Boolean),interactive:true})}<p class="field-hint" id="grid-count">${values.filter(Boolean).length} of ${d.level} cells selected. Blank slots count as missed cells.</p>`;
 if(d.kind==='missing')special=`<p class="kicker">These objects remain</p><div class="object-tray remaining-tray">${d.meta.pool.map(w=>`<div class="object-tile">${memObject(w)}</div>`).join('')}</div><p>Name the ${d.level} missing objects, in any order.</p>`;
 if(d.kind==='symbols'||d.kind==='ordering')special=`<p>${d.kind==='symbols'?'Tap symbols to rebuild the original sequence.':'Tap the steps in the original order. The tiles are supplied as part of this cued-order task.'}</p><div class="answer-sequence" aria-live="polite">${values.map((v,i)=>`<span><small>${i+1}</small>${v?e(d.kind==='symbols'?M.SYMBOLS[v]||v:v):'—'}</span>`).join('')}</div><div class="sequence-palette ${d.kind==='ordering'?'word-palette':''}" role="group" aria-label="Available ${d.kind==='symbols'?'symbols':'steps'}">${d.meta.pool.map((value,i)=>`<button type="button" class="palette-tile" data-action="mem-pick" data-index="${i}" ${d.kind==='ordering'&&values.includes(value)?'disabled':''} aria-label="${e(value)}">${d.kind==='symbols'?`<span aria-hidden="true">${e(M.SYMBOLS[value])}</span><small>${e(value)}</small>`:e(value)}</button>`).join('')}</div><div class="btn-row">${btn('mem-undo','Undo last','ghost')}${btn('mem-clear','Clear response','ghost')}</div>`;
 const fields=['grid','symbols','ordering'].includes(d.kind)?'':`<div class="mem-answer-grid">${d.targets.map((t,i)=>{const numeric=['digits','reverse','dice','chunks'].includes(d.kind),limit=d.kind==='chunks'?3:numeric?1:300;return `<div class="field"><label for="mem-answer-${i}">${e(memPrompt(d,i))}</label><input type="text" id="mem-answer-${i}" data-mem-answer="${i}" value="${e(values?.[i]||'')}" maxlength="${limit}" ${numeric?'inputmode="numeric"':''} ${['locations','updates'].includes(d.kind)?'pattern="[A-Da-d]\\s*[1-4]"':''} autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" placeholder="${['locations','updates'].includes(d.kind)?'Cell A1–D4':d.kind==='appointments'?'HH:MM':d.kind==='chunks'?'000–999':d.kind==='dice'?'1–6':numeric?'0–9':'Leave blank if not recalled'}"></div>`;}).join('')}</div>`;
 const context=['locations','updates'].includes(d.kind)?`<details class="coordinate-reference"><summary>Blank coordinate reference (no objects)</summary>${memGrid({})}</details>`:'';
 return `<form id="mem-answer-form">${special}${context}${fields}<p class="field-hint">${s.unordered?'Order does not matter. Each target earns credit at most once.':s.cued?'The questions, labels or tiles supplied here are part of this task, not extra hints.':'Recall the original sequence'+(d.kind==='reverse'?' in reverse':' in order')+'.'} ${assisted?'Your first answer stays unchanged.':'Your study notes are hidden.'}</p><button class="btn primary" type="submit">${assisted?'Check with cues':'Lock my first answer'}</button></form>`;
}
function memCues(d){const s=M.SPECS[d.kind];return `<section class="cue-card"><p class="kicker">Separate, cue-assisted attempt</p><p class="small">${e(s.tip)} These extra notes may reveal targets; they never change your first score.</p>${['palace','pegs','digits'].includes(d.kind)&&d.anchors.length?`<ol>${d.anchors.map(t=>`<li>${e(t)}</li>`).join('')}</ol>`:''}${d.images.some(Boolean)?`<ul>${d.images.map((t,i)=>t?`<li>${i+1}. ${e(t)}</li>`:'').join('')}</ul>`:''}${d.story?`<p>${e(d.story)}</p>`:''}${!d.images.some(Boolean)&&!d.story&&!['palace','pegs','digits'].includes(d.kind)?'<p class="small muted">No personal notes were saved for this set. Try the method cue above, then compare.</p>':''}</section>`;}
function memFeedback(d,a){const r=M.score(d,a.original),ar=a.assisted?M.score(d,a.assisted):null,s=M.SPECS[d.kind],unordered=s.unordered;return `<div class="score-banner"><span>First-attempt ${memScoreLabel(d)}</span><strong>${pct(r.score)}</strong></div>${!s.cued&&!unordered?`<p class="small muted">Items recovered in any order: ${pct(r.contentScore)}. In the required positions: ${pct(r.positionScore)}.</p>`:''}${ar?`<p class="small muted">With extra cues: ${pct(ar.score)}. Only the first-attempt result sets the review schedule.</p>`:''}${d.kind==='grid'?`<p class="kicker">Original pattern</p>${memGrid({selected:d.targets})}`:d.kind==='updates'?`<p class="kicker">Final layout after all moves</p>${memGrid({items:d.anchors,positions:d.targets})}`:''}${unordered?`<p><strong>Your first response:</strong> ${a.original.filter(Boolean).map(e).join(', ')||'No items recalled.'}</p>`:''}<div class="mem-feedback-list">${d.targets.map((t,i)=>`<section class="mem-feedback-row"><span class="point-no">${i+1}</span><div>${s.cued&&d.anchors[i]?`<p class="field-hint">${e(d.anchors[i])}</p>`:''}<p><strong>${e(t)}</strong> <span class="${r.perItem[i]?'match-status':'miss-status'}">${r.perItem[i]?'✓ recalled':'not recalled'}</span></p>${!unordered?`<p class="small muted">Your first answer: ${e(a.original[i]||'—')}</p>`:''}${a.assisted&&!unordered?`<p class="field-hint">With cues: ${e(a.assisted[i]||'—')}</p>`:''}</div></section>`).join('')}</div><p class="field-hint">${unordered?'Unordered, duplicate-safe item matching.':'Exact label or position matching, not automatic meaning assessment.'} Case and punctuation are ignored; synonyms and spelling differences may still count as mismatches.</p>${a.interrupted?'<p class="small muted">This attempt was interrupted. It stays in history but does not count toward a level suggestion.</p>':''}<aside class="method-tip"><strong>Bring it back to real life</strong><p>${e(s.transfer)}</p></aside>${btn('mem-save','Save & schedule review '+icon('arrow'))}`;}
function memExerciseView(){const {a,d}=memContext();if(!d){state.memory.active=null;return memoryView();}let content='';if(a.stage==='study')content=memStudy(d);else if(a.stage==='recall')content=`<p class="recall-intro">${d.kind==='reverse'?'Begin with the last digit and work backward.':d.kind==='updates'?'Recall the final cell for each object, after all moves.':'The study source is hidden.'}</p>${memAnswerForm(d,a)}`;else if(a.stage==='choice')content=`<section class="card"><p class="kicker">First answer locked</p><h2>Ready to compare?</h2><p>Your first attempt is preserved. Check it now, or make a separate attempt with your strategy notes.</p><div class="btn-row">${btn('mem-reveal','Check my answer')}${btn('mem-hint','Try with cues','secondary')}</div></section>`;else if(a.stage==='assisted')content=`${memCues(d)}${memAnswerForm(d,a,true)}`;else if(a.stage==='feedback')content=memFeedback(d,a);else if(a.stage==='result'){const r=state.memory.records.find(r=>r.id===a.savedId),next=M.recommendation(state.memory.records,d.kind,d.level);content=`<section class="card"><p class="kicker">Practice saved</p><h2>One more connection.</h2><p>First-attempt ${memScoreLabel(d)}: <strong>${pct(r?.score)}</strong>.</p><p class="small muted">${lagLabel(a.lagMs)} since last exposure${a.interrupted?' · interrupted':''}. Next review: ${dateLabel(d.due)}.</p>${next?`<p>Three strong delayed attempts at this level. You could try ${next} ${e(memUnit(d))} next time.</p>`:''}<p>${e(M.SPECS[d.kind].transfer)}</p><div class="btn-row">${btn('mem-finish','Back to Memory '+icon('arrow'))}${btn('mem-start','Try a fresh set','secondary',`data-kind="${d.kind}"`)}</div></section>`;}
 const label={study:'Build the connection',recall:'Retrieve without looking',choice:'First attempt captured',assisted:'Add your cues',feedback:'Compare & learn',result:'Keep it for later'}[a.stage];return `<section class="page-intro"><p class="kicker">${e(d.title)}</p><h1>${label}.</h1><div class="btn-row">${btn('nav','Save & leave','ghost','data-view="today"')}${a.stage!=='result'?btn('mem-end','End exercise','ghost'):''}</div>${a.phase!=='new'?'<p class="small muted">Recall-first review. The study screen is not shown before your first answer.</p>':''}</section><section class="card mem-workspace">${content}</section>`;}
function memoryAction(el){const action=el.dataset.action,m=state.memory,{a,d}=memContext();
 if(action==='mem-filter'){if(['all','favorites',...Object.keys(M.GROUPS)].includes(el.dataset.filter))memFilter=el.dataset.filter;render(false);document.querySelector(`[data-action="mem-filter"][data-filter="${memFilter}"]`)?.focus({preventScroll:true});return;}
 if(action==='mem-favorite'){const k=el.dataset.kind;if(!M.KINDS.includes(k))return;m.favorites=m.favorites.includes(k)?m.favorites.filter(x=>x!==k):[...m.favorites,k];persist();render(false);document.querySelector(`[data-action="mem-favorite"][data-kind="${k}"]`)?.focus({preventScroll:true});return;}
 if(action==='mem-surprise'){const kinds=M.KINDS.filter(k=>(k!=='palace'||(m.palaces.find(p=>p.id===memRouteChoice)||m.palaces[0])?.places.length>=m.level)&&((memFilter==='favorites')?m.favorites.includes(k):memFilter==='all'||M.SPECS[k].group===memFilter));if(!kinds.length){toast('Choose a category with an exercise, or add favorites first.');return;}const counts=Object.fromEntries(kinds.map(k=>[k,m.records.filter(r=>r.kind===k).length])),least=Math.min(...Object.values(counts));const k=M.shuffle(kinds.filter(k=>counts[k]===least))[0];return memoryAction({dataset:{action:'mem-start',kind:k}});}
 if(action==='mem-route-toggle'){memRouteOpen=!memRouteOpen;render(false);return;}
 if(action==='mem-route-delete'){if(!confirm('Remove this route? Existing exercises retain their copied route.'))return;m.palaces=m.palaces.filter(p=>p.id!==el.dataset.id);persist();render();return;}
 if(action==='mem-start'){if(m.drills.length>=150){toast('Your collection holds 150 sets. Export a backup and delete older sets before adding more.');return;}try{let palace=m.palaces.find(p=>p.id===memRouteChoice)||m.palaces[0];const drill=M.create(el.dataset.kind,m.level,palace);m.drills.push(drill);m.active={drillId:drill.id,stage:'study',phase:'new',answers:Array(drill.level).fill(''),original:null,assisted:null,hiddenAt:0,lagMs:0,interrupted:false,savedId:null,studyIndex:0};persist();render();}catch(err){toast(err.message);}return;}
 if(action==='mem-review'){const drill=m.drills.find(x=>x.id===el.dataset.id);if(!drill)return;m.active={drillId:drill.id,stage:'recall',phase:drill.due<=Date.now()?'review':'early',answers:Array(drill.level).fill(''),original:null,assisted:null,hiddenAt:drill.lastExposedAt,lagMs:0,interrupted:false,savedId:null,studyIndex:0};persist();render();return;}
 if(action==='mem-delete'){if(!confirm('Delete this set and its results from this device?'))return;m.drills=m.drills.filter(x=>x.id!==el.dataset.id);m.records=m.records.filter(r=>r.drillId!==el.dataset.id);persist();render();return;}
 if(!a||!d)return;
 if(action==='mem-step'&&a.stage==='study'){a.studyIndex=Math.min(d.level,(a.studyIndex||0)+1);persist();render(false);document.querySelector('[data-action="mem-step"], [data-action="mem-hide"]')?.focus({preventScroll:true});return;}
 if(['mem-grid-cell','mem-pick','mem-undo','mem-clear'].includes(action)&&['recall','assisted'].includes(a.stage)){
  let values=(a.stage==='assisted'?(a.assisted??=a.original.slice()):a.answers).slice();
  if(action==='mem-grid-cell'&&d.kind==='grid'&&M.CELLS.includes(el.dataset.cell)){let chosen=values.filter(Boolean);if(chosen.includes(el.dataset.cell))chosen=chosen.filter(c=>c!==el.dataset.cell);else if(chosen.length<d.level)chosen.push(el.dataset.cell);else{toast('Tap a selected cell to remove it before adding another.');return;}values=chosen.concat(Array(d.level-chosen.length).fill(''));}
  else if(action==='mem-pick'&&['symbols','ordering'].includes(d.kind)){const val=d.meta.pool[Number(el.dataset.index)],index=values.findIndex(x=>!x);if(val==null||index<0||d.kind==='ordering'&&values.includes(val))return;values[index]=val;}
  else if(action==='mem-undo'){const idx=values.map(Boolean).lastIndexOf(true);if(idx>=0)values[idx]='';}
  else if(action==='mem-clear')values=Array(d.level).fill('');
  if(a.stage==='assisted')a.assisted=values;else a.answers=values;persist();render(false);const selector=action==='mem-grid-cell'?`[data-action="mem-grid-cell"][data-cell="${el.dataset.cell}"]`:`[data-action="${action}"]${el.dataset.index!=null?'[data-index="'+Number(el.dataset.index)+'"]':''}`;document.querySelector(selector)?.focus({preventScroll:true});return;
 }
 if(action==='mem-hide'&&a.stage==='study'){if(['symbols','reverse','updates'].includes(d.kind)&&(a.studyIndex||0)<d.level)return;d.lastExposedAt=Date.now();a.hiddenAt=d.lastExposedAt;a.stage='recall';persist();render();return;}
 if(action==='mem-hint'&&a.stage==='choice'){a.assisted=a.original.slice();a.stage='assisted';d.lastExposedAt=Date.now();persist();render();return;}
 if(action==='mem-reveal'&&a.stage==='choice'){a.stage='feedback';d.lastExposedAt=Date.now();persist();render();return;}
 if(action==='mem-save'&&a.stage==='feedback'){if(a.savedId)return;const now=Date.now(),r=M.score(d,a.original),record={id:M.id('mtry'),drillId:d.id,kind:d.kind,level:d.level,at:now,lagMs:a.lagMs,phase:a.phase,original:a.original.slice(),assisted:a.assisted?.slice()||null,score:r.score,positionScore:r.positionScore,contentScore:r.contentScore,interrupted:a.interrupted};m.records.push(record);m.records=m.records.slice(-1000);const next=C.schedule(d,r.score,a.lagMs,now);d.stage=next.stage;d.reps=next.reps;d.due=next.due;d.lastReviewed=now;d.lastExposedAt=now;a.savedId=record.id;a.stage='result';persist();render();return;}
 if(action==='mem-finish'&&a.stage==='result'){m.active=null;persist();render();return;}
 if(action==='mem-end'){if(!confirm('End this attempt? Your set and notes stay in the collection; this unfinished result will not be scored.'))return;if(['study','assisted','feedback'].includes(a.stage))d.lastExposedAt=Date.now();m.active=null;persist();render();return;}
}
$('#app').addEventListener('input',event=>{const el=event.target,{a,d}=memContext();if(!a||!d)return;if(el.matches('[data-mem-image]')&&a.stage==='study'){d.images[Number(el.dataset.memImage)]=el.value.slice(0,500);queueSave();}if(el.id==='mem-set-title'&&a.stage==='study'){d.title=el.value.slice(0,100);queueSave();}if(el.id==='mem-story'&&a.stage==='study'){d.story=el.value.slice(0,3000);queueSave();}if(el.matches('[data-mem-answer]')){const i=Number(el.dataset.memAnswer);if(a.stage==='recall')a.answers[i]=el.value.slice(0,300);else if(a.stage==='assisted'){a.assisted??=a.original.slice();a.assisted[i]=el.value.slice(0,300);}queueSave();}});
$('#app').addEventListener('change',event=>{if(event.target.id==='mem-level'){state.memory.level=Number(event.target.value);persist();render(false);$('#mem-level')?.focus({preventScroll:true});}if(event.target.id==='mem-route-choice')memRouteChoice=event.target.value;});
$('#app').addEventListener('submit',event=>{const form=event.target;
 if(form.id==='mem-route-form'){event.preventDefault();const name=form.elements.routeName.value.trim(),places=form.elements.places.value.split('\n').map(v=>v.trim()).filter(Boolean);if(state.memory.palaces.length>=12){toast('Keep up to 12 routes. Remove a route before adding another.');return;}if(!name||places.length<3||places.length>12||places.some(v=>v.length>80)||new Set(places.map(M.normal)).size!==places.length){toast('Use a name and 3–12 different places, each up to 80 characters.');return;}const p={id:M.id('palace'),name:name.slice(0,60),places};state.memory.palaces.unshift(p);memRouteChoice=p.id;memRouteOpen=false;persist();render();return;}
 if(form.id==='mem-answer-form'){event.preventDefault();const {a,d}=memContext();if(!a||!d)return;if(a.stage==='recall'){a.original=a.answers.slice();a.lagMs=Math.max(0,Date.now()-a.hiddenAt);a.stage='choice';}else if(a.stage==='assisted'){a.stage='feedback';d.lastExposedAt=Date.now();}persist();render();}
});

render();registerOffline();
